import{bQ as s,aL as i,u as t,G as e}from"./chunks/framework.DjMJXVsR.js";const k=JSON.parse('{"title":"macOS \\"应用程序已损坏，无法打开\\" 的解决方法总结","description":"","frontmatter":{"title":"macOS \\"应用程序已损坏，无法打开\\" 的解决方法总结","date":"2022-06-30T00:00:00.000Z","categories":["OS"],"tags":["macOS"]},"headers":[],"relativePath":"posts/OS/macos-app-damaged-fix.md","filePath":"posts/OS/macos-app-damaged-fix.md"}'),l={name:"posts/OS/macos-app-damaged-fix.md"};function n(p,a,o,h,r,d){return i(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="macos-应用程序已损坏-无法打开-的解决方法总结" tabindex="-1">macOS &quot;应用程序已损坏，无法打开&quot; 的解决方法总结 <a class="header-anchor" href="#macos-应用程序已损坏-无法打开-的解决方法总结" aria-label="Permalink to &quot;macOS &quot;应用程序已损坏，无法打开&quot; 的解决方法总结&quot;">​</a></h1><h2 id="问题现象" tabindex="-1">问题现象 <a class="header-anchor" href="#问题现象" aria-label="Permalink to &quot;问题现象&quot;">​</a></h2><p>在 macOS 上打开某些应用程序（尤其是从非 App Store 渠道下载的软件）时，系统可能会弹出以下提示：</p><ul><li><strong>&quot;应用程序已损坏，无法打开。您应该将它移到废纸篓。&quot;</strong></li><li><strong>&quot;无法打开应用程序，因为无法验证开发者。&quot;</strong></li><li><strong>&quot;应用程序无法打开，因为 Apple 无法检查其是否包含恶意软件。&quot;</strong></li></ul><blockquote><p>注意：这类提示<strong>不一定</strong>意味着应用真的被损坏了，更多情况下是因为 macOS 的**门禁（Gatekeeper）**安全机制阻止了未经验证的软件运行。</p></blockquote><h2 id="原因分析" tabindex="-1">原因分析 <a class="header-anchor" href="#原因分析" aria-label="Permalink to &quot;原因分析&quot;">​</a></h2><p>macOS 通过以下安全机制保护用户：</p><ol><li><strong>Gatekeeper（门禁）</strong>：默认只允许运行来自 App Store 或已认证开发者的应用。</li><li><strong>公证（Notarization）</strong>：Apple 对开发者提交的应用进行自动化安全检查。</li><li><strong>隔离属性（Quarantine）</strong>：从互联网下载的文件会被打上隔离标记 <code>com.apple.quarantine</code>。</li></ol><p>当应用没有通过上述检查时，就会被阻止运行。</p><h2 id="解决方案" tabindex="-1">解决方案 <a class="header-anchor" href="#解决方案" aria-label="Permalink to &quot;解决方案&quot;">​</a></h2><h3 id="方法一-移除隔离属性-最常用" tabindex="-1">方法一：移除隔离属性（最常用） <a class="header-anchor" href="#方法一-移除隔离属性-最常用" aria-label="Permalink to &quot;方法一：移除隔离属性（最常用）&quot;">​</a></h3><p>这是最常见也最有效的解决方法，通过 <code>xattr</code> 命令移除应用上的隔离标记：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 移除单个应用的隔离属性</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.apple.quarantine</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Applications/XXX.app</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 示例：移除 Chrome 的隔离属性</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.apple.quarantine</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Applications/Google</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Chrome.app</span></span></code></pre></div><p>参数说明：</p><ul><li><code>-r</code>：递归处理目录</li><li><code>-d</code>：删除指定属性</li><li><code>com.apple.quarantine</code>：隔离属性名</li></ul><blockquote><p><strong>注意</strong>：不建议直接对 <code>/Applications/</code> 整个目录执行此操作（<code>sudo xattr -dr com.apple.quarantine /Applications/</code>），这会移除所有应用的隔离属性，降低系统安全性。请针对具体应用操作。</p></blockquote><p>执行后，再次双击应用即可正常运行。</p><h3 id="方法二-允许任何来源的应用" tabindex="-1">方法二：允许任何来源的应用 <a class="header-anchor" href="#方法二-允许任何来源的应用" aria-label="Permalink to &quot;方法二：允许任何来源的应用&quot;">​</a></h3><p>macOS 默认隐藏了&quot;任何来源&quot;选项，但可以通过命令行开启：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 开启&quot;任何来源&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --master-disable</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 关闭&quot;任何来源&quot;（恢复默认设置）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --master-enable</span></span></code></pre></div><p>开启后，可以在 <strong>系统设置 → 隐私与安全性 → 安全性</strong> 中看到&quot;任何来源&quot;选项已被选中。</p><blockquote><p><strong>注意</strong>：开启&quot;任何来源&quot;会降低系统安全性，建议在安装完需要的软件后重新关闭。</p></blockquote><h3 id="方法三-临时绕过-gatekeeper" tabindex="-1">方法三：临时绕过 Gatekeeper <a class="header-anchor" href="#方法三-临时绕过-gatekeeper" aria-label="Permalink to &quot;方法三：临时绕过 Gatekeeper&quot;">​</a></h3><p>如果只是想临时运行某个被阻止的应用，而不想修改全局设置，可以：</p><ol><li><p><strong>右键点击应用</strong> → 选择 <strong>&quot;打开&quot;</strong></p><p>或者</p></li><li><p><strong>按住 Control 键点击应用</strong> → 选择 <strong>&quot;打开&quot;</strong></p><p>这样会弹出一个确认对话框，点击 <strong>&quot;仍要打开&quot;</strong> 即可。</p></li></ol><h3 id="方法四-使用命令行直接运行" tabindex="-1">方法四：使用命令行直接运行 <a class="header-anchor" href="#方法四-使用命令行直接运行" aria-label="Permalink to &quot;方法四：使用命令行直接运行&quot;">​</a></h3><p>如果以上方法都无效，可以尝试通过命令行直接运行应用的可执行文件：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 进入应用包内容</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Applications/XXX.app/Contents/MacOS/</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 直接运行可执行文件</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./可执行文件名</span></span></code></pre></div><p>这种方法会绕过 Gatekeeper，但可能会在终端中显示一些日志信息。</p><h3 id="方法五-签名应用-针对开发者或高级用户" tabindex="-1">方法五：签名应用（针对开发者或高级用户） <a class="header-anchor" href="#方法五-签名应用-针对开发者或高级用户" aria-label="Permalink to &quot;方法五：签名应用（针对开发者或高级用户）&quot;">​</a></h3><p>如果应用没有有效的开发者签名，可以使用自签名证书进行本地签名：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 使用 ad-hoc 签名（不需要开发者账号）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codesign</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --deep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sign</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Applications/XXX.app</span></span></code></pre></div><p>参数说明：</p><ul><li><code>--force</code>：强制重新签名</li><li><code>--deep</code>：递归签名所有嵌套组件</li><li><code>--sign -</code>：使用 ad-hoc 签名（仅本地有效）</li></ul><h3 id="方法六-检查应用完整性" tabindex="-1">方法六：检查应用完整性 <a class="header-anchor" href="#方法六-检查应用完整性" aria-label="Permalink to &quot;方法六：检查应用完整性&quot;">​</a></h3><p>如果应用确实可能被损坏（如下载不完整），可以验证一下：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 检查应用包的完整性</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">spctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -vv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Applications/XXX.app</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 检查签名信息</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codesign</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -dvv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Applications/XXX.app</span></span></code></pre></div><h2 id="各种报错对应的解决方案速查表" tabindex="-1">各种报错对应的解决方案速查表 <a class="header-anchor" href="#各种报错对应的解决方案速查表" aria-label="Permalink to &quot;各种报错对应的解决方案速查表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>报错信息</th><th>推荐解决方案</th></tr></thead><tbody><tr><td>应用程序已损坏，无法打开</td><td>方法一：移除隔离属性</td></tr><tr><td>无法验证开发者</td><td>方法三：右键/Control + 点击打开</td></tr><tr><td>Apple 无法检查其是否包含恶意软件</td><td>方法一 + 方法二</td></tr><tr><td>应用闪退或无响应</td><td>方法四：命令行运行查看日志，或重新下载安装</td></tr></tbody></table><h2 id="安全建议" tabindex="-1">安全建议 <a class="header-anchor" href="#安全建议" aria-label="Permalink to &quot;安全建议&quot;">​</a></h2><ol><li><strong>尽量从官方渠道下载软件</strong>：优先选择 App Store 或软件官方网站。</li><li><strong>谨慎开启&quot;任何来源&quot;</strong>：安装完成后建议关闭该选项。</li><li><strong>不要随意移除系统级隔离属性</strong>：只对你信任且确认来源可靠的软件进行操作。</li><li><strong>保持系统更新</strong>：macOS 的安全更新会修复已知漏洞。</li><li><strong>使用杀毒软件</strong>：如果需要运行大量未经验证的软件，建议安装 macOS 上的安全软件。</li></ol><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li><a href="https://support.apple.com/zh-cn/guide/mac-help/mh40616/mac" target="_blank" rel="noreferrer">Apple 官方支持：在 Mac 上安全地打开 App</a></li><li><a href="https://developer.apple.com/documentation/security/notarizing_macos_software_before_distribution" target="_blank" rel="noreferrer">Apple Developer：Notarizing macOS Software Before Distribution</a></li></ul>`,43)])])}const g=s(l,[["render",n]]);export{k as __pageData,g as default};
